// Rekap harian untuk Telegram: klik LP, chat masuk, closing, rasio, omzet.

const TZ = 'Asia/Jakarta';

function dayKey(value) {
  const t = Date.parse(value);
  if (Number.isNaN(t)) return '';
  return new Date(t).toLocaleDateString('en-CA', { timeZone: TZ }); // YYYY-MM-DD
}

function pct(a, b) {
  return b ? (Math.round((a / b) * 1000) / 10).toString().replace('.', ',') + '%' : '-';
}

function idr(n) {
  return 'Rp' + Math.round(n || 0).toLocaleString('id-ID');
}

const PAID_STATUSES = ['confirmed', 'in_process', 'ready', 'shipped', 'completed'];

// Closing: COD (tidak dibatalkan) atau transfer yang sudah dibayar/confirmed di Scalev.
function isClosing(o) {
  if (o.status === 'canceled' || o.status === 'closed') return false;
  if (o.method === 'cod') return true;
  return o.payment_status === 'paid' || o.payment_status === 'settled' || PAID_STATUSES.includes(o.status);
}

function dailyRecap({ clicks = [], leads = [], orders = [] }, now = new Date()) {
  const today = dayKey(now.toISOString());
  const clickToday = clicks.filter((c) => dayKey(c.clicked_at) === today);
  const newChats = leads.filter((l) => dayKey(l.first_chat_at) === today);
  const activeChats = leads.filter((l) => dayKey(l.last_chat_at) === today);
  const allToday = orders.filter((o) => dayKey(o.created_at) === today);
  const ordersToday = allToday.filter(isClosing);
  const waitingTransfer = allToday.filter((o) => !isClosing(o) && o.method !== 'cod' && o.status !== 'canceled');
  // Closing = pembeli unik (1 nomor = 1 closing; order dobel/tes dari nomor yang sama tidak menggelembungkan rasio).
  const buyers = new Set(ordersToday.map((o) => o.phone || o.order_id)).size;
  const cod = ordersToday.filter((o) => o.method === 'cod');
  const omzet = ordersToday.reduce((s, o) => s + Number(o.total || 0), 0);
  const produk = ordersToday.reduce((s, o) => s + Number(o.price || 0), 0);
  const fromAds = ordersToday.filter((o) => o.ref).length;
  const tanggal = new Date(now).toLocaleDateString('id-ID', { timeZone: TZ, weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' });

  const text = [
    `📊 *REKAP AI CS* — ${tanggal}`,
    '',
    `🖱️ Klik tombol WA (LP): ${clickToday.length}`,
    `💬 Chat masuk (lead baru): ${newChats.length}`,
    `🗨️ Chat aktif hari ini: ${activeChats.length}`,
    `🛒 Closing: ${buyers} pembeli • ${ordersToday.length} order (COD ${cod.length} • Transfer lunas ${ordersToday.length - cod.length})`,
    `⏳ Transfer menunggu pembayaran: ${waitingTransfer.length}`,
    '',
    `📈 Rasio closing / chat aktif: ${pct(buyers, activeChats.length)}`,
    `📈 Rasio chat masuk / klik LP: ${pct(newChats.length, clickToday.length)}`,
    '',
    `💰 Omzet (total bayar): ${idr(omzet)}`,
    `🧴 Nilai produk: ${idr(produk)}`,
    `🎯 Closing dari iklan (ada kode ref): ${fromAds}`,
  ].join('\n');

  return { text, today, counts: { clicks: clickToday.length, newChats: newChats.length, activeChats: activeChats.length, orders: ordersToday.length, omzet, produk } };
}

const rows = (name) => $(name).all().map((i) => i.json).filter((r) => r && Object.keys(r).length);
// Status terbaru dari Scalev (hasil node Cek Order) -> transfer baru dihitung closing kalau sudah dibayar/confirmed.
const cands = $('Pilih Order Resi').all().map((i) => i.json);
const status = {};
$('Cek Order').all().forEach((item, i) => {
  const o = (item.json && item.json.data) || item.json || {};
  if (cands[i] && cands[i].scalev_id) status[cands[i].scalev_id] = { status: o.status, payment_status: o.payment_status };
});
const orders = rows('Ambil Order').map((o) => ({ ...o, ...(status[o.scalev_id] || {}) }));
const recap = dailyRecap({ clicks: rows('Ambil Klik LP'), leads: rows('Ambil Leads'), orders });
return [{ json: recap }];

// Konfigurasi Scalev per store. ID diambil dari output workflow "AI Agent CS - Scalev Setup".
// Workflow produksi memakai profil 'prod'; workflow TEST memakai profil 'test' (diganti saat build).

const STORE_PROFILE = 'prod';

const STORES = {
  prod: {
    storeId: 99062, // MODERN STORE (khusus order AI; dulu Filomall Beauty 2709)
    storeUniqueId: 'store_4iBGfe6BvEtOt3L6Jgji8Xzx',
    variants: {
      B1G1: { variantId: 8419, variantUniqueId: 'variant_T2ffVOfNELb6rwSTNTf9xw8A' }, // 2 Salep Glowing Filo (139.000)
      B2G2: { variantId: 8421, variantUniqueId: 'variant_EWWpG6ef8GdXo617vHyFEyP6' }, // 4 Salep Glowing Filo (219.000)
    },
    namePrefix: '', // contoh '[TEST AI] ' untuk menandai order tes
  },
  test: {
    storeId: 0, // ISI: store_id store tes
    storeUniqueId: 'ISI_STORE_UNIQUE_ID_TES',
    variants: {
      B1G1: { variantId: 0, variantUniqueId: 'ISI_VARIANT_B1G1_TES' },
      B2G2: { variantId: 0, variantUniqueId: 'ISI_VARIANT_B2G2_TES' },
    },
    namePrefix: '[TES BOT] ',
  },
};

const ACTIVE_STORE = STORES[STORE_PROFILE];

const SCALEV = {
  storeId: ACTIVE_STORE.storeId,
  storeUniqueId: ACTIVE_STORE.storeUniqueId,
  namePrefix: ACTIVE_STORE.namePrefix,
  warehouseCity: 'Surabaya', // gudang asal
  providerCode: 'mengantar',
  courierPattern: /j\s*&?\s*t|jnt/i, // JNT (J&T Express)
  codFeeRate: 0.03, // 3% dari (harga produk + ongkir)
  codFeeName: 'Biaya COD 3%',
  codRoundTo: 500, // total COD dibulatkan ke atas (Mengantar: 149.350 -> 149.500)
  duplicateOrderHours: 6, // cegah order dobel dari nomor yang sama
};

// Paket yang bisa di-order lewat bot.
const PACKAGES = {
  SalGlow: {
    B1G1: {
      label: 'SalGlow Beli 1 Gratis 1',
      pcs: 2, // jumlah salep untuk catatan order
      note: 'Beli 1 Gratis 1 (2 pcs) + bonus sunscreen + eyeliner',
      price: 139000,
      weight: 200, // gram, total paket
      items: [{ ...ACTIVE_STORE.variants.B1G1, qty: 1 }],
    },
    B2G2: {
      label: 'SalGlow Beli 2 Gratis 2',
      pcs: 4,
      note: 'Beli 2 Gratis 2 (4 pcs) + bonus sunscreen + eyeliner',
      price: 219000,
      weight: 400,
      items: [{ ...ACTIVE_STORE.variants.B2G2, qty: 1 }],
    },
  },
};

// Batch resi harian: order yang sudah confirmed & belum punya resi -> generate AWB sekaligus.

const RESI_LOOKBACK_DAYS = 3; // transfer yang baru dibayar 1-2 hari kemudian tetap ikut

// Kandidat dari tabel aics_orders (baris lama tanpa scalev_id dilewati).
function resiCandidates(rows, now = Date.now()) {
  const seen = new Set();
  return rows.filter((r) => {
    if (!r || !r.scalev_id || seen.has(r.scalev_id)) return false;
    seen.add(r.scalev_id);
    const at = Date.parse(r.created_at);
    return !Number.isNaN(at) && now - at < RESI_LOOKBACK_DAYS * 86400000;
  });
}

// Isi paket + pembayaran + nominal, contoh "2 salepglowing, sunscreen, eyeliner, COD, 149.500".
function packingText(row) {
  const pkg = (PACKAGES.SalGlow || {})[row.paket] || {};
  const method = row.method === 'cod' ? 'COD' : 'TRANSFER';
  return `${pkg.pcs || '?'} salepglowing, sunscreen, eyeliner, ${method}, ${Number(row.total || 0).toLocaleString('id-ID')}`;
}

// Siap resi: status confirmed (COD otomatis; transfer setelah admin konfirmasi pembayaran) dan belum ada resi.
function readyForResi(order) {
  const o = (order && order.data) || order || {};
  return o.status === 'confirmed' && !o.shipment_receipt;
}

function resiReport(response, orders) {
  const r = (response && response.data) || response || {};
  const ok = Object.entries(r.successes || {});
  const fail = Object.entries(r.failures || {});
  const name = (id) => (orders.find((o) => o.scalev_id === id || o.order_id === id) || {}).order_id || id;
  const lines = ['🧾 BATCH RESI HARIAN', '', `✅ Resi terbit: ${ok.length}`];
  ok.forEach(([id, resi]) => lines.push(`• ${name(id)}: ${resi}`));
  if (fail.length) {
    lines.push('', `⚠️ Gagal: ${fail.length}`);
    fail.forEach(([id, msg]) => lines.push(`• ${name(id)}: ${msg}`));
  }
  if (!ok.length && !fail.length) lines.push('', `Respons Scalev: ${JSON.stringify(response).slice(0, 300)}`);
  lines.push('', 'Silakan print semua label di Mengantar/Scalev.');
  return lines.join('\n');
}

// Laporan saat tidak ada order yang siap dibuatkan resi (tetap dikirim supaya admin tahu batch jalan).
function resiEmptyReport(cands, checks) {
  const lines = ['🧾 BATCH RESI', '', 'Tidak ada order siap resi (confirmed & belum ada resi).'];
  const real = cands.filter((c) => c && c.scalev_id);
  if (real.length) {
    lines.push('', 'Order AI 3 hari terakhir:');
    real.forEach((c, i) => {
      const o = (checks[i] && (checks[i].data || checks[i])) || {};
      lines.push(`• ${c.order_id} (${c.method}): ${o.status || '?'}${o.shipment_receipt ? ', resi ' + o.shipment_receipt : ''}`);
    });
  }
  return lines.join('\n');
}

const rows = $('Ambil Order').all().map((i) => i.json);
const list = resiCandidates(rows).map((r) => ({ json: r }));
// Tetap 1 item supaya rekap tetap terkirim walau tidak ada order (Cek Order -> 404, diabaikan).
return list.length ? list : [{ json: { scalev_id: '', placeholder: true } }];
